package pl.pricemonitor.simulator.model;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

/** Content of simulator-data.json (generated by tools/generate_sample_data.py). */
public record SimulatorData(List<ShopData> shops, SellerData seller) {

    public record ShopData(String code, String name, String format, List<OfferData> offers) {
    }

    /**
     * @param truth key of the catalog product this offer really is (P01 = produkt.id 1, ...), {@code null} for
     *              offers that must not be matched; never published in the feed
     */
    public record OfferData(String id, String name, String brand, String gtin, String mpn,
                            Map<String, String> attributes, String condition, BigDecimal price, BigDecimal shipping,
                            boolean available, String url, String truth) {
    }

    public record SellerData(String apiKey, List<SellerProduct> products) {
    }

    public record SellerProduct(String id, String name, BigDecimal price) {
    }
}
